record.field:
registry_model = env['x_hr.recruitment_document'].sudo()
sign_request_model = env['sign.request'].sudo()
attachment_model = env['ir.attachment'].sudo()

action = False


def reload_checklist(rec):
    view = env.ref('hr_recruitment_custom.view_required_document_checklist_form_controlled', raise_if_not_found=False)
    action = {
        'type': 'ir.actions.act_window',
        'name': rec.x_name or 'Required Document Checklist',
        'res_model': rec._name,
        'res_id': rec.id,
        'view_mode': 'form',
        'target': 'current',
    }
    if view:
        action['views'] = [(view.id, 'form')]
    return action


def toast(title, message, kind='warning', sticky=False, next_action=False):
    params = {
        'title': title,
        'message': message,
        'type': kind,
        'sticky': sticky,
    }
    if next_action:
        params['next'] = next_action
    return {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': params}


def looks_like_certificate(attachment):
    name = (attachment.name or '').lower()
    return (
        'certificate' in name
        or 'completion' in name
        or 'completed' in name
        or 'history' in name
        or 'audit' in name
        or 'trail' in name
        or 'شهادة' in name
        or 'إكمال' in name
        or 'اكمال' in name
    )


for rec in records.sudo():
    applicant = rec.x_applicant_id
    if not applicant:
        action = toast('Applicant missing', 'F-0003 checklist is not linked to an applicant.', 'warning', True, reload_checklist(rec))
        continue

    registry_doc = registry_model.search([
        ('x_document_type', '=', 'required_documents_checklist'),
        ('x_source_model', '=', 'x_hr.applicant_required_document_checklist'),
        ('x_source_res_id', '=', rec.id),
        ('x_signature_mode', '=', 'native_sign'),
    ], order='x_version desc, id desc', limit=1)

    if not registry_doc:
        registry_doc = registry_model.search([
            ('x_document_type', '=', 'required_documents_checklist'),
            ('x_source_model', '=', 'x_hr.applicant_required_document_checklist'),
            ('x_source_res_id', '=', rec.id),
        ], order='x_version desc, id desc', limit=1)

    if not registry_doc:
        registry_doc = registry_model.search([
            ('x_document_type', '=', 'required_documents_checklist'),
            ('x_applicant_id', '=', applicant.id),
            ('x_signature_mode', '=', 'native_sign'),
            ('x_sign_request_res_id', '!=', False),
        ], order='x_version desc, id desc', limit=1)

    if not registry_doc:
        action = toast('No F-0003 Sign registry row', 'No native Odoo Sign recruitment document registry row was found for this F-0003 checklist.', 'warning', True, reload_checklist(rec))
        continue

    if not registry_doc.x_sign_request_res_id:
        action = toast('No linked Sign request', 'The F-0003 recruitment document registry row has no linked Odoo Sign request ID.', 'warning', True, reload_checklist(rec))
        continue

    sign_request = sign_request_model.browse(registry_doc.x_sign_request_res_id)
    if not sign_request.exists():
        registry_doc.write({'x_sign_request_state': 'missing_sign_request'})
        action = toast('Missing Sign request', 'The linked Odoo Sign request no longer exists or cannot be accessed.', 'warning', True, reload_checklist(rec))
        continue

    request_state = sign_request.state or 'unknown'
    registry_doc.write({
        'x_sign_request_state': request_state,
        'x_sign_request_reference': sign_request.reference or registry_doc.x_sign_request_reference,
    })

    if request_state not in ['signed', 'completed']:
        if rec.x_state != 'signature_requested':
            rec.write({'x_state': 'signature_requested'})
        rec.message_post(body='F-0003 native Odoo Sign request is not fully signed yet. Current Sign request state: %s. Ask the signer to complete signing, then sync again.' % request_state)
        applicant.message_post(body='F-0003 native Odoo Sign completion sync checked request %s. Current state: %s. Registry was not closed.' % (sign_request.id, request_state))
        action = toast('F-0003 not fully signed yet', 'Odoo Sign request is still in state: %s. Ask the signer to complete signing, then sync again.' % request_state, 'warning', False, reload_checklist(rec))
        continue

    completed_attachments = sign_request.completed_document_attachment_ids if 'completed_document_attachment_ids' in sign_request._fields else attachment_model.browse([])

    related_attachments = attachment_model.search([
        ('res_model', '=', 'sign.request'),
        ('res_id', '=', sign_request.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    applicant_attachments = attachment_model.search([
        ('res_model', '=', 'hr.applicant'),
        ('res_id', '=', applicant.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    checklist_attachments = attachment_model.search([
        ('res_model', '=', rec._name),
        ('res_id', '=', rec.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    all_attachments = completed_attachments | related_attachments | applicant_attachments | checklist_attachments

    signed_native = False
    certificate_native = False

    for attachment in all_attachments:
        if rec.x_pdf_attachment_id and attachment.id == rec.x_pdf_attachment_id.id:
            continue
        if registry_doc.x_generated_attachment_id and attachment.id == registry_doc.x_generated_attachment_id.id:
            continue
        if looks_like_certificate(attachment):
            if not certificate_native:
                certificate_native = attachment
        elif not signed_native:
            signed_native = attachment

    if not signed_native:
        registry_doc.write({
            'x_sign_request_state': 'signed_no_business_document_found',
            'x_notes': ((registry_doc.x_notes or '') + '\nOdoo Sign request %s is signed/completed, but no signed business PDF was found during sync on %s.' % (sign_request.id, datetime.datetime.now())).strip(),
        })
        action = toast('Signed PDF not found', 'The Sign request is signed/completed, but the completed signed PDF was not found yet. Try Sync again after Odoo finishes processing.', 'warning', True, reload_checklist(rec))
        continue

    signed_copy = registry_doc.x_signed_attachment_id
    if signed_copy and looks_like_certificate(signed_copy):
        signed_copy = False
    if signed_copy and rec.x_pdf_attachment_id and signed_copy.id == rec.x_pdf_attachment_id.id:
        signed_copy = False

    if not signed_copy:
        signed_name = signed_native.name or ('Signed F-0003 - %s.pdf' % (applicant.partner_name or applicant.name or applicant.display_name))
        if signed_native.res_model == 'hr.applicant' and signed_native.res_id == applicant.id:
            signed_copy = signed_native
        else:
            signed_copy = signed_native.copy({
                'name': signed_name,
                'res_model': 'hr.applicant',
                'res_id': applicant.id,
            })

    certificate_copy = registry_doc.x_sign_certificate_attachment_id
    if not certificate_copy and certificate_native:
        certificate_name = certificate_native.name or ('Certificate of completion - F-0003 - %s.pdf' % (applicant.partner_name or applicant.name or applicant.display_name))
        if certificate_native.res_model == 'hr.applicant' and certificate_native.res_id == applicant.id:
            certificate_copy = certificate_native
        else:
            certificate_copy = certificate_native.copy({
                'name': certificate_name,
                'res_model': 'hr.applicant',
                'res_id': applicant.id,
            })

    signed_on = False
    if sign_request.write_date:
        signed_on = sign_request.write_date

    signer_items = sign_request.request_item_ids.filtered(lambda item: item.state == 'completed')
    for signer_item in signer_items:
        if signer_item.write_date and (not signed_on or signer_item.write_date > signed_on):
            signed_on = signer_item.write_date

    if not signed_on and 'completion_date' in sign_request._fields and sign_request.completion_date:
        signed_on = datetime.datetime.combine(sign_request.completion_date, datetime.time(12, 0, 0))

    if not signed_on:
        signed_on = datetime.datetime.now()

    registry_values = {
        'x_state': 'signed',
        'x_signed_attachment_id': signed_copy.id,
        'x_sign_completed_attachment_id': signed_copy.id,
        'x_sign_completed_on': signed_on,
        'x_signed_on': signed_on,
        'x_sign_request_state': request_state,
        'x_sign_request_reference': sign_request.reference or registry_doc.x_sign_request_reference,
        'x_responsible_user_id': env.user.id,
        'x_source_model': 'x_hr.applicant_required_document_checklist',
        'x_source_res_id': rec.id,
        'x_notes': ((registry_doc.x_notes or '') + '\nNative Odoo Sign completion synced for F-0003 on %s. Sign request ID: %s. Signed artifact: %s.' % (datetime.datetime.now(), sign_request.id, signed_copy.name)).strip(),
    }
    if certificate_copy:
        registry_values['x_sign_certificate_attachment_id'] = certificate_copy.id

    registry_doc.write(registry_values)

    rec.write({
        'x_state': 'signed',
        'x_signed_on': signed_on,
        'x_signed_attachment_id': signed_copy.id,
    })

    rec.message_post(body='F-0003 native Odoo Sign completion synced. Signed artifact linked: %s.' % signed_copy.name)
    applicant.message_post(body='F-0003 Required Documents Checklist signed through native Odoo Sign. Signed F-0003 artifact and certificate, where available, were linked to the recruitment document registry.')

    action = toast('F-0003 signed', 'Signed F-0003 result synced. Signed artifact and certificate, where available, were linked to the recruitment registry.', 'success', False, reload_checklist(rec))
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

for rec in records:
    if rec.x_pdf_attachment_id:
        action = {
            'type': 'ir.actions.act_url',
            'url': '/web/content/%s?download=true' % rec.x_pdf_attachment_id.id,
            'target': 'self',
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'No generated PDF',
                'message': 'No generated F-0003 PDF is linked to this checklist.',
                'type': 'warning',
                'sticky': False,
            }
        }
    break

